import React, {useEffect, useMemo} from 'react'

import {AnalyticsProvider} from '@github-ui/analytics-provider'
import type {FileOverviewPayload} from '@github-ui/code-view-types'
import {CurrentRepositoryProvider} from '@github-ui/current-repository'
/* eslint-disable-next-line @github-ui/github-monorepo/no-use-app-payload --
   useAppPayload is deprecated. See
   https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
import {AppPayloadContext} from '@github-ui/react-core/use-app-payload'
// eslint-disable-next-line no-restricted-imports
import {ScreenSize, ScreenSizeProvider} from '@github-ui/screen-size'
import {AllShortcutsEnabledProvider} from '@github-ui/code-view-shared/contexts/AllShortcutsEnabledContext'
import {CodeViewBannersProvider} from '@github-ui/code-view-shared/contexts/CodeViewBannersContext'
import {CopilotSettingsProvider} from '@github-ui/code-view-shared/contexts/CopilotSettingsContext'
import {CurrentTreeProvider} from '@github-ui/code-view-shared/contexts/CurrentTreeContext'
import {FileQueryProvider} from '@github-ui/code-view-shared/contexts/FileQueryContext'
import {RefInfoProvider} from '@github-ui/code-view-shared/contexts/RefInfoContext'
import {PathProvider} from '@github-ui/code-view-shared/contexts/PathContext'
import {ActionProvider} from '@github-ui/code-view-shared/contexts/ActionContext'
import {useFilePagePayload} from '@github-ui/code-view-shared/hooks/use-file-page-payload'
import {CurrentUserProvider} from '@github-ui/current-user'
import {useCanonicalObject} from '@github-ui/code-view-shared/hooks/use-canonical-object'
import {UserNameDisplayContextProvider} from '@github-ui/profile-reference/UserNameDisplayContext'

import OverviewContent from './components/OverviewContent'
import {EditPermissionsProvider} from '@github-ui/code-view-shared/contexts/EditPermissionsContext'
import {useWebVitals} from '@github-ui/use-web-vitals'
import {sendCustomMetric} from '@github-ui/stats'

export function ReposOverviewLegacy({
  initialPayload,
  appPayload,
}: {
  initialPayload: FileOverviewPayload
  appPayload: unknown
}) {
  const payload = useFilePagePayload(initialPayload) as FileOverviewPayload

  const [repo] = React.useState(initialPayload?.repo)
  const [user] = React.useState(initialPayload?.currentUser)
  const refInfo = useCanonicalObject(payload.refInfo)

  const appName = 'react-code-view-overview'
  const category = ''
  const metadata = useMemo(() => ({}), [])

  useWebVitals('hpc', event => {
    if (!event.detail.hpc) return
    sendCustomMetric({
      name: 'CODE_VIEW_REPO_OVERVIEW_HPC',
      value: event.detail.hpc,
      tags: {
        app: 'repos-overview',
        soft: String(event.detail.soft),
        ssr: String(event.detail.ssr),
        mechanism: String(event.detail.mechanism),
      },
    })
  })

  useWebVitals('inp', event => {
    if (!event.detail.inp) return
    sendCustomMetric({
      name: 'CODE_VIEW_REPO_OVERVIEW_INP',
      value: event.detail.inp,
      tags: {
        app: 'repos-overview',
        inpInteractionType: event.detail.inpInteractionType || 'unknown',
        inpEventType: event.detail.inpEventType || 'unknown',
        inpBottleneck: event.detail.inpBottleneck || 'unknown',
      },
    })
  })

  useEffect(() => {
    const footer = document.querySelector('.footer')
    if (footer) {
      footer.querySelector('.mt-6')?.classList.replace('tmp-mt-6', 'mt-0')
      footer.querySelector('.border-top')?.classList.remove('border-top')
    }
  }, [])

  return (
    <AppPayloadContext value={appPayload}>
      <ScreenSizeProvider initialValue={ScreenSize.xxxlarge}>
        <AnalyticsProvider appName={appName} category={category} metadata={metadata}>
          <CurrentUserProvider user={user}>
            <CurrentRepositoryProvider repository={repo}>
              <PathProvider path={payload.path}>
                <ActionProvider action="tree">
                  <CopilotSettingsProvider copilotAccessAllowed={payload.copilotAccessAllowed ?? false}>
                    <RefInfoProvider refInfo={refInfo}>
                      <EditPermissionsProvider
                        canEdit={payload.refInfo.canEdit}
                        canEditOnDefaultBranch={payload.refInfo.canEditOnDefaultBranch}
                        fileExistsOnDefault={payload.refInfo.fileExistsOnDefault}
                      >
                        <CodeViewBannersProvider>
                          <AllShortcutsEnabledProvider allShortcutsEnabled={payload.allShortcutsEnabled}>
                            <FileQueryProvider>
                              <CurrentTreeProvider payload={payload.tree}>
                                <UserNameDisplayContextProvider value={payload.userNameDisplayConfiguration}>
                                  <OverviewContent payload={payload} />
                                </UserNameDisplayContextProvider>
                              </CurrentTreeProvider>
                            </FileQueryProvider>
                          </AllShortcutsEnabledProvider>
                        </CodeViewBannersProvider>
                      </EditPermissionsProvider>
                    </RefInfoProvider>
                  </CopilotSettingsProvider>
                </ActionProvider>
              </PathProvider>
            </CurrentRepositoryProvider>
          </CurrentUserProvider>
        </AnalyticsProvider>
      </ScreenSizeProvider>
    </AppPayloadContext>
  )
}
